function dotsNew(n,m){ n=n||4; m=m||4; return { n:n, m:m, h:new Array((n+1)*m).fill(false), v:new Array(n*(m+1)).fill(false), boxes:new Array(n*m).fill(null), turn:'A', scores:{A:0,B:0} }; }
function dotsBoxComplete(s, br, bc){ var e=dotsBoxEdges(s,br,bc); return e.top&&e.bottom&&e.left&&e.right; }
function dotsBoxEdges(s, br, bc){ return { top:s.h[br*s.m+bc], bottom:s.h[(br+1)*s.m+bc], left:s.v[br*(s.m+1)+bc], right:s.v[br*(s.m+1)+bc+1] }; }
function dotsAdd(s, type, i){
  if(type==='h'){ if(i<0||i>=s.h.length||s.h[i]) return {box:false}; s.h[i]=true; }
  else { if(i<0||i>=s.v.length||s.v[i]) return {box:false}; s.v[i]=true; }
  var completed=[], r, c;
  if(type==='h'){ r=Math.floor(i/s.m); c=i%s.m; if(r-1>=0 && dotsBoxComplete(s,r-1,c)) completed.push([r-1,c]); if(r<s.n && dotsBoxComplete(s,r,c)) completed.push([r,c]); }
  else { var per=s.m+1; r=Math.floor(i/per); c=i%per; if(c-1>=0 && dotsBoxComplete(s,r,c-1)) completed.push([r,c-1]); if(c<s.m && dotsBoxComplete(s,r,c)) completed.push([r,c]); }
  var owner=s.turn; completed.forEach(function(b){ var bi=b[0]*s.m+b[1]; if(s.boxes[bi]===null){ s.boxes[bi]=owner; s.scores[owner]++; } });
  if(completed.length===0){ s.turn = s.turn==='A'?'B':'A'; }
  return {box:completed.length>0, boxes:completed, turn:s.turn};
}
function dotsDone(s){ return s.boxes.every(function(b){return b!==null;}); }
var EXPORTS={dotsNew:dotsNew,dotsAdd:dotsAdd,dotsBoxComplete:dotsBoxComplete,dotsDone:dotsDone};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DotsForgePure = EXPORTS; }
